import {LEVELS,WORLD} from './levels.mjs?v=1.1.0';
const bounded=(v,a,b)=>Math.max(a,Math.min(b,v));
function distanceToLine(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=dx||dy?bounded(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy),0,1):0;return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
function simplifySegment(segment,epsilon){if(segment.length<3)return segment;const keep=new Set([0,segment.length-1]),stack=[[0,segment.length-1]];while(stack.length){const [a,b]=stack.pop();let max=epsilon,at=-1;for(let i=a+1;i<b;i++){const d=distanceToLine(segment[i],segment[a],segment[b]);if(d>max){max=d;at=i;}}if(at!==-1){keep.add(at);stack.push([a,at],[at,b]);}}return [...keep].sort((a,b)=>a-b).map(i=>segment[i]);}
export function compactPath(path,limit=850){const segments=[];for(const p of path){if(p.move||!segments.length)segments.push([]);segments.at(-1).push(p);}let epsilon=.7,result=path;for(let pass=0;pass<12;pass++){result=segments.flatMap(segment=>simplifySegment(segment,epsilon).map((p,i)=>({...p,move:i===0})));if(result.length<=limit)break;epsilon*=1.65;}if(result.length>limit){result=result.slice(-limit);result[0]={...result[0],move:true};}return result;}
export function normalizePrint(data,expectedIndex){if(!data||typeof data!=='object'||!Number.isInteger(data.index)||data.index<0||data.index>=LEVELS.length||expectedIndex!==undefined&&data.index!==expectedIndex||!Array.isArray(data.path)||data.path.length<2||data.path.length>900)return null;
 const level=LEVELS[data.index];const path=[];for(const p of data.path){if(!Array.isArray(p)||!Number.isFinite(p[0])||!Number.isFinite(p[1])||p[0]<0||p[0]>WORLD.w||p[1]<0||p[1]>WORLD.h)return null;path.push([Math.round(p[0]*10)/10,Math.round(p[1]*10)/10,p[2]?1:0,bounded(Number.isFinite(p[3])?p[3]:.5,.1,1)]);}path[0][2]=1;
 const boat=Array.isArray(data.boat)&&data.boat.length===3&&data.boat.every(Number.isFinite)?[bounded(data.boat[0],0,WORLD.w),bounded(data.boat[1],0,WORLD.h),data.boat[2]% (Math.PI*2)]:[level.goal.x,level.goal.y,0];
 return {version:1,index:data.index,path,boat,lights:level.lights.map((_,i)=>data.lights?.[i]===true),woven:[...new Set((Array.isArray(data.woven)?data.woven:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<level.rocks.length))],shots:bounded(Math.round(data.shots)||0,0,100000),tears:bounded(Math.round(data.tears)||0,0,100000),time:bounded(Number.isFinite(data.time)?data.time:0,0,1000000)};
}
export function makePrint(voyage){const path=[...voyage.path,{x:voyage.boat.x,y:voyage.boat.y,weight:.2}];return normalizePrint({index:voyage.index,path:compactPath(path).map(p=>[p.x,p.y,p.move?1:0,p.weight||.3]),boat:[voyage.boat.x,voyage.boat.y,voyage.boat.angle],lights:voyage.collected.map(Boolean),woven:(voyage.stitched||[]).flatMap((v,i)=>v?[i]:[]),shots:voyage.shots,tears:voyage.tears,time:voyage.time});}
export function sceneForPrint(data){const print=normalizePrint(data);if(!print)return null;const level=LEVELS[print.index];return {index:print.index,level,path:print.path.map(([x,y,move,weight])=>({x,y,move:!!move,weight})),boat:{x:print.boat[0],y:print.boat[1],angle:print.boat[2],vx:0,vy:0},collected:print.lights,stitched:level.rocks.map((_,i)=>print.woven.includes(i)),stitchTimes:level.rocks.map(()=>0),bloomTimes:level.lights.map(()=>0),loops:[],time:Math.max(2,print.time),state:'clear',respawn:0,shots:print.shots,tears:print.tears,lightCount:print.lights.filter(Boolean).length,ready:print.lights.every(Boolean)};}
